using System.IO.Compression;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text.Json;
using Jindan.Contracts;
using Jindan.Contracts.Drive;
using Jindan.Core;
using Jindan.Desktop.Contracts;
using Jindan.Infrastructure;
using Jindan.Modules.Files;

static class Program
{
    [DllImport("user32.dll")] static extern bool PrintWindow(nint hwnd, nint hdc, uint flags);
    static string output = ""; static int pass, fail; static bool completed; static readonly List<object> checks = [];
    static IEnumerable<Control> Tree(Control c) { yield return c; foreach (Control child in c.Controls) foreach (var nested in Tree(child)) yield return nested; }
    static void Assert(bool condition, string message) { if (!condition) throw new Exception(message); }
    static async Task Test(string name, Func<Task> action) { try { await action(); pass++; checks.Add(new { name, passed = true }); Console.WriteLine("PASS " + name); } catch (Exception e) { fail++; checks.Add(new { name, passed = false, error = e.ToString() }); Console.WriteLine("FAIL " + name + ": " + e.Message); } }
    static async Task Expect(string code, Func<Task> action) { try { await action(); } catch (DriveBoundaryException e) { Assert(e.Code == code, e.Code); return; } throw new Exception("Expected " + code); }
    static async Task AwaitPause(Task ready, Task archive) { var next = await Task.WhenAny(ready, archive).WaitAsync(TimeSpan.FromSeconds(10)); if (next == archive) { await archive; throw new Exception("Archive completed without reaching the intended pause"); } await ready; }
    static void Capture(Form form, string name) { form.Update(); using var image = new Bitmap(form.Width, form.Height); using (var g = Graphics.FromImage(image)) { var hdc = g.GetHdc(); try { Assert(PrintWindow(form.Handle, hdc, 2), "PrintWindow failed"); } finally { g.ReleaseHdc(hdc); } } Assert(Enumerable.Range(0, 40).Select(i => image.GetPixel(i * (image.Width - 1) / 39, i * (image.Height - 1) / 39).ToArgb()).Distinct().Count() > 1, "Uniform native frame is not evidence"); image.Save(Path.Combine(output, name + ".png")); }
    [STAThread] static int Main(string[] args)
    {
        ApplicationConfiguration.Initialize(); output = Path.GetFullPath(args.FirstOrDefault() ?? Path.Combine("artifacts", "drive-ui70-" + Guid.NewGuid().ToString("N"))); if (Directory.Exists(output)) throw new Exception("Fresh output required"); Directory.CreateDirectory(output);
        var installed = args.ElementAtOrDefault(1); var loaded = new List<object>(); foreach (var pair in new (Type Type, string Relative)[] { (typeof(WorkRecord), "Jindan.Contracts.dll"), (typeof(DomainRules), "Jindan.Core.dll"), (typeof(RecordDocument), "Jindan.Desktop.Contracts.dll"), (typeof(LocalWorkspace), "Jindan.Infrastructure.dll"), (typeof(FileDocument), "modules/files/Jindan.Modules.Files.dll") }) { var sha = Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(pair.Type.Assembly.Location))); if (installed is not null) Assert(sha == Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(Path.Combine(installed, pair.Relative)))), "Loaded DLL differs: " + pair.Relative); loaded.Add(new { relative = pair.Relative, path = pair.Type.Assembly.Location, sha256 = sha }); }
        using var store = new LocalWorkspace(Path.Combine(output, "data")); var actor = store.BootstrapAsync("Drive local synthetic", "drive-local-70-test", true).GetAwaiter().GetResult(); var services = new Services(actor, store); var module = new Jindan.Modules.Files.Module(); module.Initialize(services); store.RegisterSchema(new("projects", "Projects", [new("title", "Title", Required: true)], false));
        var p = store.SaveAsync(actor, new(null, "projects", null, 0, new() { ["title"] = "합성 캐시 프로젝트" })).GetAwaiter().GetResult(); var q = store.SaveAsync(actor, new(null, "projects", null, 0, new() { ["title"] = "분리 프로젝트" })).GetAwaiter().GetResult(); var context = new DocumentContext("drive-ui70", "files", p.Id, actor.Id);
        using var form = new Form { Text = "Drive70 합성 UI 검증", Width = 1100, Height = 800 }; using var files = new FileDocument(services, module.Schema, context) { Dock = DockStyle.Fill }; form.Controls.Add(files); using var drive = new DriveCacheWindow(services, context);
        form.Shown += async (_, _) =>
        {
            try
            {
                await files.Ready; drive.Show(form); await Task.Delay(150); string fixturePath = Path.Combine(output, "fixture.json"); var fixture = await drive.CreateExampleAsync(); await File.WriteAllTextAsync(fixturePath, JsonSerializer.Serialize(fixture));
                await Test("Files exposes explicit offline Drive-cache command with no default remote action", () => { var action = Tree(files).OfType<ToolStrip>().SelectMany(x => x.Items.OfType<ToolStripButton>()).Single(x => x.Text == "Drive 목록 캐시 · 로컬 시험"); Assert(action.Enabled && Tree(drive).OfType<Label>().Single().Text.Contains("실제 Drive 미연결"), "Offline scope not exposed"); Capture(drive, "01-offline-empty-native"); return Task.CompletedTask; });
                await Test("native fixture load hides system entries and renders scoped cached hierarchy", async () => { await drive.OpenFixtureAsync(fixturePath); var tree = Tree(drive).OfType<TreeView>().Single(); var grid = Tree(drive).OfType<DataGridView>().Single(); Assert(tree.Nodes.Count == 1 && tree.Nodes[0].Nodes.Count == 1 && grid.Rows.Count == 2 && !grid.Rows.Cast<DataGridViewRow>().Any(r => r.Cells[0].Value as string == ".system"), "Scoped cache UI incorrect"); tree.SelectedNode = tree.Nodes[0].Nodes[0]; Assert(grid.Rows.Count == 1 && grid.Rows[0].Cells[0].Value as string == "합성 보고서.pdf", "Folder selection not reflected"); drive.PerformLayout(); var actions = Tree(drive).OfType<FlowLayoutPanel>().Single(); var header = grid.RectangleToScreen(grid.GetCellDisplayRectangle(0, -1, true)); Assert(header.Height > 0 && header.Top >= actions.RectangleToScreen(actions.ClientRectangle).Bottom && grid.Height > 200, "Cache list header covered by action controls"); await Task.Delay(80); Capture(drive, "02-cached-folder-native"); });
                await Test("native offline failure keeps immediate persisted rows and displays failure code", async () => { Tree(drive).OfType<CheckBox>().Single(x => x.Name == "DriveOfflineSimulation").Checked = true; await drive.RefreshAllAsync(); Assert(Tree(drive).OfType<DataGridView>().Single().Rows.Count == 1 && Tree(drive).OfType<Label>().Single().Text.Contains("DRIVE_LISTING_FAILED"), "Offline fallback not visible"); Capture(drive, "03-offline-cache-native"); });
                await Test("cache reopen and new window preserve same project metadata without content download", async () => { await drive.ReopenAsync(); Assert(Tree(drive).OfType<TreeView>().Single().Nodes[0].Nodes.Count == 1, "Reopen lost folders"); using var reopened = new DriveCacheWindow(services, context); reopened.Show(form); await reopened.OpenFixtureAsync(fixturePath); Assert(Tree(reopened).OfType<DataGridView>().Single().Rows.Count == 2, "New-window hydration missing"); Capture(reopened, "04-reopened-cache-native"); reopened.Close(); });
                await Test("UI rejects foreign project fixture before changing cached hierarchy", async () => { var foreignPath = Path.Combine(output, "foreign.json"); await File.WriteAllTextAsync(foreignPath, JsonSerializer.Serialize(fixture with { Scope = fixture.Scope with { ProjectId = q.Id } })); await Expect("DRIVE_SCOPE_DENIED", () => drive.OpenFixtureAsync(foreignPath)); Assert(Tree(drive).OfType<TreeView>().Single().Nodes[0].Nodes.Count == 1, "Foreign fixture changed UI"); });
                await Test("UI cancel button cancels owned refresh and retains durable metadata", async () => { Tree(drive).OfType<CheckBox>().Single(x => x.Name == "DriveOfflineSimulation").Checked = false; Tree(drive).OfType<CheckBox>().Single(x => x.Name == "DriveDelaySimulation").Checked = true; var refresh = drive.RefreshAllAsync(); for (var i = 0; i < 50 && !Tree(drive).OfType<Label>().Single().Text.Contains("갱신 중"); i++) await Task.Delay(5); Tree(drive).OfType<Button>().Single(x => x.Text == "취소").PerformClick(); try { await refresh; throw new Exception("Cancellation not observed"); } catch (OperationCanceledException) { } await drive.ReopenAsync(); Assert(Tree(drive).OfType<TreeView>().Single().Nodes[0].Nodes.Count == 1, "Canceled refresh lost cache"); });
                drive.Close(); var original = Path.Combine(output, "original.txt"); await File.WriteAllTextAsync(original, "SYNTHETIC fixture bytes; no company values"); var sha = SHA256.HashData(await File.ReadAllBytesAsync(original)); WorkRecord? child = null; WorkRecord? parent = null; WorkRecord? row = null;
                await Test("recursive folder ZIP preserves hierarchy empty folder manifest and exact original bytes", async () => { parent = await files.CreateFolderAsync("조사 자료"); child = await files.CreateFolderAsync("측정 자료", parent.Id); await files.CreateFolderAsync("빈 폴더", parent.Id); row = await files.ImportPathAsync(original); await files.MoveToFolderAsync(row.Id, child.Id); var outputZip = await files.ExportFolderZipAsync(parent.Id); using var zip = ZipFile.OpenRead(outputZip); var entry = zip.Entries.Single(e => e.Name.EndsWith("original.txt", StringComparison.Ordinal)); using var stream = entry.Open(); Assert(SHA256.HashData(stream).SequenceEqual(sha), "ZIP content differs"); Assert(zip.Entries.Count(e => e.FullName.EndsWith('/')) == 3 && entry.FullName.Split('/').Length == 3 && zip.GetEntry("manifest.json") is not null, "Nested/empty folder structure missing"); Assert(SHA256.HashData(await File.ReadAllBytesAsync(original)).SequenceEqual(sha), "Source changed"); });
                await Test("folder ZIP rejects foreign project and canceled request without partial output", async () => { var other = await store.SaveAsync(actor, new(null, "file-folders", q.Id, 0, new() { ["title"] = "다른 프로젝트 폴더" })); var before = Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), "*.zip").Length; try { await files.ExportFolderZipAsync(other.Id); throw new Exception("Foreign folder accepted"); } catch (InvalidOperationException) { } try { await files.ExportFolderZipAsync(parent!.Id, new CancellationToken(true)); throw new Exception("Cancellation ignored"); } catch (OperationCanceledException) { } Assert(Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), "*.zip").Length == before, "Failed export left output"); });
                await Test("folder ZIP rejects tampered immutable asset before publishing archive", async () => { var asset = await store.GetAsync(actor, row!.Fields["assetId"]); var before = Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), "*.zip").Length; var bytes = await File.ReadAllBytesAsync(asset.StoredPath); try { await File.WriteAllTextAsync(asset.StoredPath, "tampered isolated fixture"); try { await files.ExportFolderZipAsync(parent!.Id); throw new Exception("Tampered asset accepted"); } catch (WorkspaceException e) { Assert(e.Code == "CORRUPT_ASSET", e.Code); } } finally { await File.WriteAllBytesAsync(asset.StoredPath, bytes); } Assert(Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), "*.zip").Length == before && SHA256.HashData(await File.ReadAllBytesAsync(original)).SequenceEqual(sha), "Tamper test changed source/output"); });
                await Test("same-content different-name import keeps its alias while sharing immutable asset", async () => { await files.NavigateFolderAsync(child!.Id); var alias = Path.Combine(output, "alias.txt"); File.Copy(original, alias); var imported = await files.ImportPathAsync(alias); Assert(imported.Fields["title"] == "alias.txt" && imported.Fields["assetId"] == row!.Fields["assetId"] && imported.Id != row.Id, "Alias collapsed into original filename"); await store.DeleteAsync(actor, "files", imported.Id, imported.Revision, true); });
                await Test("actual duplicate-choice dialog skip rename and cancel preserve the existing file", async () => { var conflictDir = Path.Combine(output, "conflict"); Directory.CreateDirectory(conflictDir); var conflicting = Path.Combine(conflictDir, "original.txt"); await File.WriteAllTextAsync(conflicting, "SYNTHETIC different immutable bytes"); var originalAsset = row!.Fields["assetId"]; var beforeAssets = Directory.GetFiles(Path.Combine(store.DataRoot, "assets"), "*.blob").Length;
                    async Task Choose(string buttonName) { using var timer = new System.Windows.Forms.Timer { Interval = 10 }; timer.Tick += (_, _) => { var modal = Application.OpenForms.Cast<Form>().SingleOrDefault(f => f.Name == "DuplicateFileDecision"); if (modal is null) return; timer.Stop(); Capture(modal, "05-duplicate-" + buttonName + "-native"); Tree(modal).OfType<Button>().Single(b => b.Name == buttonName).PerformClick(); }; timer.Start(); try { await files.ImportWithDuplicateChoiceAsync(conflicting); } finally { timer.Stop(); } }
                    await Choose("DuplicateSkip"); Assert(Directory.GetFiles(Path.Combine(store.DataRoot, "assets"), "*.blob").Length == beforeAssets, "Skipped file still imported asset bytes"); await Choose("DuplicateRename"); var copied = (await store.ListAsync(actor, new RecordQuery("files", p.Id))).Single(r => r.Fields["title"] == "original (1).txt"); Assert(copied.Fields["assetId"] != originalAsset && (await store.ListAsync(actor, new RecordQuery("files", p.Id))).Single(r => r.Id == row.Id).Fields["assetId"] == originalAsset, "Rename replaced original asset"); try { await Choose("DuplicateCancel"); throw new Exception("Choice cancellation ignored"); } catch (OperationCanceledException) { } await store.DeleteAsync(actor, "files", copied.Id, copied.Revision, true); Assert(SHA256.HashData(await File.ReadAllBytesAsync(original)).SequenceEqual(sha), "Duplicate policy changed external source"); });
                await Test("completed archive staging is not published after document context switches", async () => { var controlled = new InterleavingAssets(store); using var isolated = new FileDocument(new ControlledServices(actor, store, controlled), module.Schema, context); form.Controls.Add(isolated); isolated.BringToFront(); await isolated.Ready.WaitAsync(TimeSpan.FromSeconds(10)); var ready = new TaskCompletionSource(); var release = new TaskCompletionSource(); controlled.AfterGet = async call => { if (call == 2) { ready.SetResult(); await release.Task; } }; var before = Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), "*.zip").Length; var archive = isolated.ExportFolderZipAsync(parent!.Id); await AwaitPause(ready.Task, archive); Assert(Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), ".folder-stage-*.tmp").Length == 1, "Test did not reach completed staging"); isolated.SetContext(context with { ProjectId = q.Id }); release.SetResult(); try { await archive; throw new Exception("Stale context published"); } catch (InvalidOperationException) { } Assert(Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), "*.zip").Length == before && Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), ".folder-stage-*.tmp").Length == 0, "Stale context left published/partial archive"); });
                await Test("persisted project-access revocation after staging blocks archive publication", async () => { var user = await store.SaveUserAsync(actor, null, "Archive scoped editor", "editor", [p.Id], false, "archive-editor-70"); var editor = await store.LoginAsync("Archive scoped editor", "archive-editor-70"); var controlled = new InterleavingAssets(store); using var isolated = new FileDocument(new ControlledServices(editor, store, controlled), module.Schema, context with { ContextId = "revoked-archive", UserId = editor.Id }); form.Controls.Add(isolated); isolated.BringToFront(); await isolated.Ready.WaitAsync(TimeSpan.FromSeconds(10)); var ready = new TaskCompletionSource(); var release = new TaskCompletionSource(); controlled.AfterGet = async call => { if (call == 2) { ready.SetResult(); await release.Task; } }; var before = Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), "*.zip").Length; var archive = isolated.ExportFolderZipAsync(parent!.Id); await AwaitPause(ready.Task, archive); Assert(Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), ".folder-stage-*.tmp").Length == 1, "Test did not reach completed staging"); await store.SaveUserAsync(actor, user.Id, user.DisplayName, "editor", [], false, null); release.SetResult(); try { await archive; throw new Exception("Revoked user published"); } catch (WorkspaceException error) { Assert(error.Code == "FORBIDDEN", error.Code); } Assert(Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), "*.zip").Length == before && Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), ".folder-stage-*.tmp").Length == 0, "Revoked export left archive"); });
                await Test("metadata revision change after staging fails closed before publish", async () => { var controlled = new InterleavingAssets(store); using var isolated = new FileDocument(new ControlledServices(actor, store, controlled), module.Schema, context); form.Controls.Add(isolated); isolated.BringToFront(); await isolated.Ready.WaitAsync(TimeSpan.FromSeconds(10)); var ready = new TaskCompletionSource(); var release = new TaskCompletionSource(); controlled.AfterGet = async call => { if (call == 2) { ready.SetResult(); await release.Task; } }; var before = Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), "*.zip").Length; var archive = isolated.ExportFolderZipAsync(parent!.Id); await AwaitPause(ready.Task, archive); var current = (await store.ListAsync(actor, new RecordQuery("files", p.Id))).Single(r => r.Id == row!.Id); var changed = new Dictionary<string, string>(current.Fields) { ["content"] = "synthetic metadata revision" }; row = await store.SaveAsync(actor, new(current.Id, current.Kind, current.ProjectId, current.Revision, changed)); release.SetResult(); try { await archive; throw new Exception("Stale metadata published"); } catch (InvalidOperationException) { } Assert(Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), "*.zip").Length == before && Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), ".folder-stage-*.tmp").Length == 0, "Revision change left archive"); });
                await Test("cancel after complete staging removes only owned temporary output", async () => { var controlled = new InterleavingAssets(store); using var isolated = new FileDocument(new ControlledServices(actor, store, controlled), module.Schema, context); form.Controls.Add(isolated); isolated.BringToFront(); await isolated.Ready.WaitAsync(TimeSpan.FromSeconds(10)); var ready = new TaskCompletionSource(); var release = new TaskCompletionSource(); controlled.AfterGet = async call => { if (call == 2) { ready.SetResult(); await release.Task; } }; var sentinel = Path.Combine(store.DataRoot, "exports", "existing-preserved.zip"); await File.WriteAllBytesAsync(sentinel, [4, 5, 6]); var before = Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), "*.zip").Length; using var cancel = new CancellationTokenSource(); var archive = isolated.ExportFolderZipAsync(parent!.Id, cancel.Token); await AwaitPause(ready.Task, archive); Assert(Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), ".folder-stage-*.tmp").Length == 1, "Test did not reach staging"); cancel.Cancel(); release.SetResult(); try { await archive; throw new Exception("Late cancellation ignored"); } catch (OperationCanceledException) { } Assert(Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), "*.zip").Length == before && Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), ".folder-stage-*.tmp").Length == 0 && (await File.ReadAllBytesAsync(sentinel)).SequenceEqual(new byte[] { 4, 5, 6 }), "Cancellation changed existing output"); });
                await Test("protected export-root injection is rejected before any directory write", async () => { using var isolated = new FileDocument(new ControlledServices(actor, store, store, "F:/jindan"), module.Schema, context); form.Controls.Add(isolated); isolated.BringToFront(); await isolated.Ready.WaitAsync(TimeSpan.FromSeconds(10)); await Expect("DRIVE_PROTECTED_PATH", () => isolated.ExportFolderZipAsync(parent!.Id)); });
                await Test("real NTFS junction in exports ancestor is rejected before publication", async () => { var temp = Path.GetFullPath(Path.GetTempPath()).TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar; var isolatedRoot = Path.Combine(temp, "jindan-drive70-junction-" + Guid.NewGuid().ToString("N")); Assert(Path.GetFullPath(isolatedRoot).StartsWith(temp, StringComparison.OrdinalIgnoreCase) && !Directory.Exists(isolatedRoot), "Owned temporary fixture path invalid"); Directory.CreateDirectory(isolatedRoot); var target = Path.Combine(isolatedRoot, "target"); Directory.CreateDirectory(target); var linked = Path.Combine(isolatedRoot, "exports"); var info = new System.Diagnostics.ProcessStartInfo("cmd.exe") { UseShellExecute = false, CreateNoWindow = true, RedirectStandardOutput = true, RedirectStandardError = true }; foreach (var value in new[] { "/c", "mklink", "/J", linked, target }) info.ArgumentList.Add(value); using (var process = System.Diagnostics.Process.Start(info)!) { await process.WaitForExitAsync(); Assert(process.ExitCode == 0 && File.GetAttributes(linked).HasFlag(FileAttributes.ReparsePoint), "Owned junction creation failed; do not claim rejection tested"); } try { using var isolated = new FileDocument(new ControlledServices(actor, store, store, isolatedRoot), module.Schema, context); form.Controls.Add(isolated); isolated.BringToFront(); await isolated.Ready.WaitAsync(TimeSpan.FromSeconds(10)); await Expect("DRIVE_PATH", () => isolated.ExportFolderZipAsync(parent!.Id)); Assert(!Directory.EnumerateFileSystemEntries(target).Any(), "Linked target received output"); } finally { Assert(Path.GetFullPath(linked).StartsWith(Path.GetFullPath(isolatedRoot) + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase) && File.GetAttributes(linked).HasFlag(FileAttributes.ReparsePoint), "Cleanup target is not the owned junction"); Directory.Delete(linked, false); Directory.Delete(target, false); Directory.Delete(isolatedRoot, false); } });
                await Test("fresh local-store session retains folder asset bindings and cache namespaces", async () => { using var reopened = new LocalWorkspace(store.DataRoot); var login = await reopened.LoginAsync("Drive local synthetic", "drive-local-70-test"); var saved = (await reopened.ListAsync(login, new RecordQuery("files", p.Id))).Single(); Assert(saved.Id == row!.Id && saved.Fields["folderId"] == child!.Id && Directory.GetFiles(Path.Combine(store.DataRoot, "drive-cache70"), "*.json").Length == 1, "Restart changed scope or bindings"); });
            }
            catch (Exception error) { fail++; checks.Add(new { name = "setup", passed = false, error = error.ToString() }); }
            finally { await File.WriteAllTextAsync(Path.Combine(output, "RESULT.json"), JsonSerializer.Serialize(new { pass, fail, loaded, checks, installed, syntheticOnly = true, realDrive = "NotConfigured", normalOwnedWindowClose = true, reportReady = false, supervisorAccepted = false }, new JsonSerializerOptions { WriteIndented = true })); completed = true; drive.Close(); form.Close(); }
        };
        Application.Run(form); Console.WriteLine($"DRIVE_UI70 pass={pass} fail={fail} output={output}"); return completed && fail == 0 ? 0 : 1;
    }
    sealed class Services(Identity actor, LocalWorkspace store) : IWorkspaceServices { public Identity Actor => actor; public IWorkspaceData Data => store; public IIdentityService Identities => store; public IAssetService Assets => store; public ILayoutStore Layout => store; public string DataRoot => store.DataRoot; public IReportService Reports { get; } = new NoReport(); }
    sealed class ControlledServices(Identity actor, LocalWorkspace store, IAssetService assets, string? dataRoot = null) : IWorkspaceServices { public Identity Actor => actor; public IWorkspaceData Data => store; public IIdentityService Identities => store; public IAssetService Assets => assets; public ILayoutStore Layout => store; public string DataRoot => dataRoot ?? store.DataRoot; public IReportService Reports { get; } = new NoReport(); }
    sealed class InterleavingAssets(IAssetService inner) : IAssetService { int calls; public Func<int, Task>? AfterGet { get; set; } public async Task<AssetInfo> GetAsync(Identity actor, string id, CancellationToken ct = default) { var value = await inner.GetAsync(actor, id, ct); if (AfterGet is not null) await AfterGet(++calls); return value; } public Task<AssetInfo> ImportAsync(Identity actor, string project, string source, CancellationToken ct = default) => inner.ImportAsync(actor, project, source, ct); public Task ExportAsync(Identity actor, string id, string destination, CancellationToken ct = default) => inner.ExportAsync(actor, id, destination, ct); }
    sealed class NoReport : IReportService { public Task<ReportReply> ExecuteAsync(DocumentContext c, ReportCommand m, IProgress<ReportProgress>? p = null, CancellationToken ct = default) => throw new NotSupportedException(); public Task AcknowledgeReviewAsync(DocumentContext c, string s, string f, string r, CancellationToken ct = default) => throw new NotSupportedException(); public void Invalidate(string id) { } }
}
